package cn.campus.schedule;
import android.app.*;
import android.content.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;

final class TimetableTransfer {
    final MainActivity a;
    TimetableTransfer(MainActivity a){this.a=a;}
    void menu(){new AlertDialog.Builder(a).setTitle("课表文件").setItems(new String[]{"导出课表","导入课表","恢复上次导入前的课表"},(d,w)->{try{if(w==0)a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"同学日程-课表-"+LocalDate.now()+".json"),81);else if(w==1)a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),82);else{File file=new File(a.getFilesDir(),"timetable-backup.json");try(InputStream in=new FileInputStream(file)){preview(validate(read(in)));}}}catch(Exception e){a.toast(w==2?"还没有可恢复的课表备份":"无法打开文件选择器");}}).show();}
    static JSONObject export(JSONObject data){JSONObject r=new JSONObject();AgendaFeatures.put(r,"format","student-schedule-timetable");AgendaFeatures.put(r,"version",1);for(String k:new String[]{"semester","configured","totalWeeks","starts","ends","courses","labels"})AgendaFeatures.put(r,k,data.opt(k));return AgendaFeatures.cloneJson(r);}
    static JSONObject read(InputStream in)throws Exception{if(in==null)throw new IOException("无法读取文件");ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1){if(b.size()+n>2*1024*1024)throw new IOException("课表文件不能超过 2MB");b.write(chunk,0,n);}return new JSONObject(b.toString("UTF-8"));}
    static JSONObject validate(JSONObject input){
        if(!input.optString("format").equals("student-schedule-timetable")||input.optInt("version")!=1)throw new IllegalArgumentException("不是支持的本 App 课表文件");
        JSONObject result=new JSONObject();AgendaFeatures.put(result,"format","student-schedule-timetable");AgendaFeatures.put(result,"version",1);AgendaFeatures.put(result,"semester",LocalDate.parse(input.optString("semester")).toString());int weeks=input.optInt("totalWeeks");if(weeks<1||weeks>52)throw new IllegalArgumentException("学期周数无效");AgendaFeatures.put(result,"totalWeeks",weeks);AgendaFeatures.put(result,"configured",input.optBoolean("configured",true));
        JSONArray starts=input.optJSONArray("starts"),ends=input.optJSONArray("ends");if(starts==null||ends==null||starts.length()!=12||ends.length()!=12)throw new IllegalArgumentException("课表须包含 12 节课的时间");int previous=-1;for(int i=0;i<12;i++){int start=ScheduleRules.minutes(starts.optString(i)),end=ScheduleRules.minutes(ends.optString(i));if(start>=end||start<previous)throw new IllegalArgumentException("节次时间无效或重叠");previous=end;}AgendaFeatures.put(result,"starts",starts);AgendaFeatures.put(result,"ends",ends);
        JSONArray original=input.optJSONArray("courses");if(original==null||original.length()>2000)throw new IllegalArgumentException("课程列表无效或过大");JSONArray courses=new JSONArray();for(int i=0;i<original.length();i++){JSONObject c=original.optJSONObject(i);if(c==null||c.optString("title").trim().isEmpty()||c.optString("title").length()>500||c.optInt("from")<1||c.optInt("to")>12||c.optInt("from")>c.optInt("to"))throw new IllegalArgumentException("课程字段无效");Set<Integer> days=CourseRules.days(c);if(days.isEmpty()||days.stream().anyMatch(d->d<1||d>7))throw new IllegalArgumentException("上课星期无效");ScheduleRules.weeks(c.optString("weeks"),weeks);JSONObject clean=new JSONObject();for(String k:new String[]{"title","room","from","to","weeks"})AgendaFeatures.put(clean,k,c.opt(k));AgendaFeatures.put(clean,"id",UUID.randomUUID().toString());AgendaFeatures.put(clean,"days",new JSONArray(days));AgendaFeatures.put(clean,"day",days.iterator().next());AgendaFeatures.put(clean,"tags",c.optJSONArray("tags")==null?new JSONArray():c.optJSONArray("tags"));courses.put(clean);}AgendaFeatures.put(result,"courses",courses);
        JSONArray labels=input.optJSONArray("labels");if(labels==null)labels=new JSONArray();if(labels.length()>1000)throw new IllegalArgumentException("标签过多");JSONArray cleanLabels=new JSONArray();for(int i=0;i<labels.length();i++){JSONObject label=labels.optJSONObject(i);if(label==null||label.optString("name").length()>100||label.optString("name").trim().isEmpty())throw new IllegalArgumentException("标签无效");JSONObject clean=new JSONObject();AgendaFeatures.put(clean,"id",label.optString("id"));AgendaFeatures.put(clean,"name",label.optString("name"));AgendaFeatures.put(clean,"color",label.optInt("color",0xff0868ce));cleanLabels.put(clean);}AgendaFeatures.put(result,"labels",cleanLabels);return result;
    }
    static boolean sameSettings(JSONObject a,JSONObject b){for(String key:new String[]{"semester","totalWeeks","starts","ends"})if(!String.valueOf(a.opt(key)).equals(String.valueOf(b.opt(key))))return false;return true;}
    static boolean sameCourse(JSONObject a,JSONObject b,int weeks){return a.optString("title").equals(b.optString("title"))&&a.optString("room").equals(b.optString("room"))&&a.optInt("from")==b.optInt("from")&&a.optInt("to")==b.optInt("to")&&ScheduleRules.weeks(a.optString("weeks"),weeks).equals(ScheduleRules.weeks(b.optString("weeks"),weeks));}
    static JSONObject merge(JSONObject current,JSONObject file,boolean replace){
        if(!replace&&!sameSettings(current,file)&&current.optJSONArray("courses").length()>0)throw new IllegalArgumentException("两份课表的学期或节次时间不同，请选择替换，或先统一设置");
        JSONObject next=AgendaFeatures.cloneJson(current);if(replace||current.optJSONArray("courses").length()==0)for(String k:new String[]{"semester","totalWeeks","starts","ends","configured"})AgendaFeatures.put(next,k,file.opt(k));
        JSONArray labels=next.optJSONArray("labels"),incoming=file.optJSONArray("labels");Map<String,String> map=new HashMap<>();for(int i=0;i<incoming.length();i++){JSONObject source=incoming.optJSONObject(i);String id="";for(int j=0;j<labels.length();j++)if(labels.optJSONObject(j).optString("name").equals(source.optString("name")))id=labels.optJSONObject(j).optString("id");if(id.isEmpty()){JSONObject label=AgendaFeatures.cloneJson(source);id=UUID.randomUUID().toString();AgendaFeatures.put(label,"id",id);labels.put(label);}map.put(source.optString("id"),id);}
        JSONArray courses=replace?new JSONArray():next.optJSONArray("courses");JSONArray additions=file.optJSONArray("courses");for(int i=0;i<additions.length();i++){JSONObject c=AgendaFeatures.cloneJson(additions.optJSONObject(i));Set<Integer> remaining=CourseRules.days(c);for(int j=0;j<courses.length();j++)if(sameCourse(c,courses.optJSONObject(j),next.optInt("totalWeeks")))remaining.removeAll(CourseRules.days(courses.optJSONObject(j)));if(remaining.isEmpty())continue;AgendaFeatures.put(c,"days",new JSONArray(remaining));AgendaFeatures.put(c,"day",remaining.iterator().next());JSONArray tags=new JSONArray();for(String tag:AgendaFeatures.strings(c.optJSONArray("tags")))if(map.containsKey(tag))tags.put(map.get(tag));AgendaFeatures.put(c,"tags",tags);AgendaFeatures.put(c,"id",UUID.randomUUID().toString());courses.put(c);}AgendaFeatures.put(next,"courses",courses);return next;
    }
    void preview(JSONObject file){int count=file.optJSONArray("courses").length();StringBuilder summary=new StringBuilder("开学日期："+file.optString("semester")+"\n学期："+file.optInt("totalWeeks")+" 周\n课程："+count+" 门\n");for(int i=0;i<Math.min(12,count);i++){JSONObject c=file.optJSONArray("courses").optJSONObject(i);summary.append("\n").append(c.optString("title")).append(" · 星期 ").append(CourseRules.days(c));}new AlertDialog.Builder(a).setTitle("导入预览").setMessage(summary.toString()).setNegativeButton("取消",null).setNeutralButton("合并",(d,w)->confirm(file,false)).setPositiveButton("替换",(d,w)->confirm(file,true)).show();}
    void confirm(JSONObject file,boolean replace){try{JSONObject next=merge(a.data,file,replace);int conflicts=0;JSONArray courses=next.optJSONArray("courses");for(int i=0;i<courses.length();i++)for(int j=i+1;j<courses.length();j++)if(CourseRules.overlaps(courses.optJSONObject(i),courses.optJSONObject(j),next.optInt("totalWeeks")))conflicts++;String message="导入后共 "+courses.length()+" 门课程。完全相同的安排已跳过。\n"+(conflicts>0?"发现 "+conflicts+" 处课程时间冲突，导入后请调整。":"未发现课程冲突。")+"\n现有课表将先备份，日程和心情不受影响。";new AlertDialog.Builder(a).setTitle(replace?"确认替换课表":"确认合并课表").setMessage(message).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->{try{try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),"timetable-backup.json"))){out.write(export(a.data).toString().getBytes(StandardCharsets.UTF_8));}if(!a.persist(next))throw new IOException();a.render();a.toast("课表导入成功");}catch(Exception e){a.toast("导入未完成，原数据已保留");}}).show();}catch(Exception e){a.toast(e.getMessage());}}
    void result(int request,int result,Intent intent){if(result!=Activity.RESULT_OK||intent==null||intent.getData()==null)return;Uri uri=intent.getData();if(request==81){try(OutputStream out=a.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();out.write(export(a.data).toString(2).getBytes(StandardCharsets.UTF_8));a.toast("课表已导出");}catch(Exception e){a.toast("导出失败，请重试");}}else if(request==82){new Thread(()->{try(InputStream in=a.getContentResolver().openInputStream(uri)){JSONObject data=validate(read(in));a.runOnUiThread(()->preview(data));}catch(Exception e){a.runOnUiThread(()->a.toast("无法导入："+(e.getMessage()==null?"文件格式无效":e.getMessage())));}}).start();}}
}
